<?php

namespace App\Controllers;

use App\Controllers\BaseController;

class Home extends BaseController
{
    // ── Features finales (intersección ANOVA + RF, igual que notebook) ────────
    // ['age','ca','cp','exang','oldpeak','slope','thal','thalach','trestbps']
    private array $featuresOrder = [
        'age','ca','cp','exang','oldpeak','slope','thal','thalach','trestbps'
    ];

    // ── Variables que se normalizan (MinMaxScaler fit sobre datos originales) ─
    private array $varsNorm = ['age','trestbps','thalach','oldpeak'];

    // ── Rangos reales del dataset (fit sobre 302 instancias únicas) ───────────
    private array $scalerMin = [
        'age'      => 29.0,
        'trestbps' => 94.0,
        'thalach'  => 71.0,
        'oldpeak'  => 0.0,
    ];
    private array $scalerMax = [
        'age'      => 77.0,
        'trestbps' => 200.0,
        'thalach'  => 202.0,
        'oldpeak'  => 6.2,
    ];

    // ── Vista principal ────────────────────────────────────────────────────────
    public function index(): string
    {
        return view('Cuerpos/heart_disease_home', $this->getImgs());
    }

    // ── Predicción ────────────────────────────────────────────────────────────
    public function predict(): string
    {
        $rules = [
            'age'      => 'required|integer|greater_than[20]|less_than[81]',
            'trestbps' => 'required|integer|greater_than[80]|less_than[211]',
            'thalach'  => 'required|integer|greater_than[60]|less_than[211]',
            'oldpeak'  => 'required|numeric|greater_than_equal_to[0]|less_than_equal_to[6.5]',
            'cp'       => 'required|in_list[0,1,2,3]',
            'ca'       => 'required|in_list[0,1,2,3,4]',
            'thal'     => 'required|in_list[0,1,2,3]',
            'exang'    => 'required|in_list[0,1]',
            'slope'    => 'required|in_list[0,1,2]',
        ];

        if (! $this->validate($rules)) {
            return view('Cuerpos/heart_disease_home', array_merge($this->getImgs(), [
                'errors' => $this->validator->getErrors(),
                'old'    => $this->request->getPost(),
            ]));
        }

        $input = [
            'age'      => (float) $this->request->getPost('age'),
            'ca'       => (float) $this->request->getPost('ca'),
            'cp'       => (float) $this->request->getPost('cp'),
            'exang'    => (float) $this->request->getPost('exang'),
            'oldpeak'  => (float) $this->request->getPost('oldpeak'),
            'slope'    => (float) $this->request->getPost('slope'),
            'thal'     => (float) $this->request->getPost('thal'),
            'thalach'  => (float) $this->request->getPost('thalach'),
            'trestbps' => (float) $this->request->getPost('trestbps'),
        ];

        $inputNorm = $this->normalize($input);
        [$prediction, $probability] = $this->knnPredict($inputNorm, 11);

        return view('Cuerpos/heart_disease_home', array_merge($this->getImgs(), [
            'prediction'  => $prediction,
            'probability' => $probability,
            'input'       => $input,
        ]));
    }

    // ── MinMax normalization ──────────────────────────────────────────────────
    private function normalize(array $input): array
    {
        $norm = $input;
        foreach ($this->varsNorm as $feat) {
            $min = $this->scalerMin[$feat];
            $max = $this->scalerMax[$feat];
            $norm[$feat] = ($input[$feat] - $min) / ($max - $min);
            $norm[$feat] = max(0.0, min(1.0, $norm[$feat]));
        }
        return $norm;
    }

    // ── KNN k=11 distancia euclidiana ─────────────────────────────────────────
    private function knnPredict(array $inputNorm, int $k): array
    {
        $training  = $this->getTrainingData();
        $distances = [];

        foreach ($training as $i => $row) {
            $dist = 0.0;
            foreach ($this->featuresOrder as $j => $feat) {
                $diff  = $inputNorm[$feat] - $row[$j];
                $dist += $diff * $diff;
            }
            $distances[$i] = sqrt($dist);
        }

        asort($distances);
        $kNearest = array_slice(array_keys($distances), 0, $k, true);

        $votes = [0 => 0, 1 => 0];
        foreach ($kNearest as $idx) {
            $votes[(int) $training[$idx][count($this->featuresOrder)]]++;
        }

        $prediction  = ($votes[1] >= $votes[0]) ? 1 : 0;
        $probability = round($votes[1] / $k, 4);

        return [$prediction, $probability];
    }

